59	static void CreateSyncBlock(PatternRewriter &rewriter, Location loc,
60	                            MLIRContext *ctx, Operation *op, int64_t id,
61	                            hivm::SyncBlockMode mode, PipeAttr pipe1,
62	                            PipeAttr pipe2) {
63	  auto syncMode = hivm::SyncBlockModeAttr::get(ctx, mode);
64	  auto newOp = rewriter.create<hivm::SyncBlockOp>(
65	      loc, syncMode, rewriter.getI16IntegerAttr(id), Value{}, pipe1, pipe2);
66	  rewriter.replaceOp(op, newOp);
67	}
