69	static CoreAndPipes GetCoreAndPipes(MLIRContext *ctx, llvm::StringRef opName,
70	                                    llvm::StringRef sender) {
71	  // Step 1: Decide pipes
72	  PipeAttr producer;
73	  PipeAttr consumer = PipeAttr::get(ctx, PIPE::PIPE_MTE2);
74	
75	  if (sender == "cube") {
76	    producer = PipeAttr::get(ctx, PIPE::PIPE_FIX);
77	  } else {
78	    producer = PipeAttr::get(ctx, PIPE::PIPE_MTE3);
79	  }
80	
81	  // Step 2: Decide core type
82	  TCoreTypeAttr core;
83	  if (sender == "cube") {
84	    if (opName == "sync_block_set")
85	      core = TCoreTypeAttr::get(ctx, TCoreType::CUBE);
86	    else
87	      core = TCoreTypeAttr::get(ctx, TCoreType::VECTOR);
88	  } else {
89	    if (opName == "sync_block_set")
90	      core = TCoreTypeAttr::get(ctx, TCoreType::VECTOR);
91	    else
92	      core = TCoreTypeAttr::get(ctx, TCoreType::CUBE);
93	  }
94	
95	  return {core, producer, consumer};
96	}
