107	    : OpRewritePattern<triton::ascend::CustomOp> {
108	  using OpRewritePattern<triton::ascend::CustomOp>::OpRewritePattern;
109	
110	  LogicalResult matchAndRewrite(triton::ascend::CustomOp op,
111	                                PatternRewriter &rewriter) const final {
112	    auto *ctx = op->getContext();
113	    auto loc = op->getLoc();
114	    auto args = op.getStrArgs();
115	    auto argAttr = dyn_cast<StringAttr>(args[0]);
116	    auto id = dyn_cast<IntegerAttr>(args[1]).getInt();
117	    llvm::StringRef opName = op.getOpName();
118	    llvm::StringRef arg = argAttr.getValue();
119	
120	    if (opName == "sync_block_all") {
121	      if (arg == "all_cube") {
122	        CreateSyncBlock(rewriter, loc, ctx, op, id,
123	                        hivm::SyncBlockMode::ALL_CUBE,
124	                        PipeAttr::get(ctx, PIPE::PIPE_FIX), hivm::PipeAttr{});
125	      } else if (arg == "all_vector") {
126	        CreateSyncBlock(rewriter, loc, ctx, op, id,
127	                        hivm::SyncBlockMode::ALL_VECTOR, hivm::PipeAttr{},
128	                        PipeAttr::get(ctx, PIPE::PIPE_MTE3));
129	      } else if (arg == "all") {
130	        CreateSyncBlock(rewriter, loc, ctx, op, id, hivm::SyncBlockMode::ALL,
131	                        PipeAttr::get(ctx, PIPE::PIPE_FIX),
132	                        PipeAttr::get(ctx, PIPE::PIPE_MTE3));
133	      } else {
134	        return EmitUnknownOpError(op, opName);
135	      }
136	      return success();
137	    }
138	
139	    if (opName == "sync_block_set") {
140	      auto [coreAttr, prodPipe, consPipe] = GetCoreAndPipes(ctx, opName, arg);
141	      rewriter.replaceOp(op, rewriter.create<hivm::SyncBlockSetOp>(
142	                                 loc, coreAttr, prodPipe, consPipe,
143	                                 rewriter.getIndexAttr(id)));
144	      return success();
145	    }
146	
147	    if (opName == "sync_block_wait") {
148	      auto [coreAttr, prodPipe, consPipe] = GetCoreAndPipes(ctx, opName, arg);
149	      rewriter.replaceOp(op, rewriter.create<hivm::SyncBlockWaitOp>(
150	                                 loc, coreAttr, prodPipe, consPipe,
151	                                 rewriter.getIndexAttr(id)));
152	      return success();
153	    }
154	
155	    return EmitUnknownOpError(op, opName);
156	  }
