6	#include "TritonToHFusion/Passes.h"
7	
8	#include "Dialect/TritonAscend/IR/TritonAscendDialect.h"
9	#include "bishengir/Dialect/HFusion/IR/HFusion.h"
10	#include "bishengir/Dialect/HFusion/IR/HFusionImpl.h"
11	#include "bishengir/Dialect/Tensor/IR/TensorImpl.h"
12	#include "mlir/Dialect/Tensor/IR/Tensor.h"
13	#include "mlir/IR/Attributes.h"
14	#include "mlir/Pass/Pass.h"
15	#include "mlir/Transforms/DialectConversion.h"
16	#include "mlir/Transforms/GreedyPatternRewriteDriver.h"
17	#include "llvm/ADT/StringRef.h"
18	#include "llvm/Support/LogicalResult.h"
19	
20	namespace mlir {
21	namespace triton {
22	#define GEN_PASS_DEF_TRITONTOHFUSION
23	#include "ascend/include/TritonToHFusion/Passes.h.inc"
24	} // namespace triton
25	} // namespace mlir
26	
27	using namespace mlir;
28	using namespace hfusion;
29	
30	namespace {
31	struct TritonModToHFusionConversion : OpRewritePattern<triton::ascend::ModOp> {
32	  using OpRewritePattern<triton::ascend::ModOp>::OpRewritePattern;
33	
34	  LogicalResult matchAndRewrite(triton::ascend::ModOp op,
35	                                PatternRewriter &rewriter) const final {
36	    auto lhsType = dyn_cast<RankedTensorType>(op.getLhs().getType());
37	    auto rhsType = dyn_cast<RankedTensorType>(op.getRhs().getType());
38	    if (!lhsType || !rhsType) {
39	      return failure();
40	    }
41	
42	    auto emptyTensor = rewriter.create<tensor::EmptyOp>(
43	        op.getLoc(), lhsType.getShape(), lhsType.getElementType());
44	    auto newOp =
45	        hfusion::createBinaryOp<hfusion::ElemwiseBinaryOp, hfusion::BinaryFn,
46	                                hfusion::BinaryFnAttr>(
47	            rewriter, op.getLoc(), hfusion::BinaryFn::mod,
48	            ValueRange({op.getLhs(), op.getRhs()}),
49	            ValueRange({emptyTensor.getResult()}));
50	
51	    rewriter.replaceOp(op, newOp->getResult(0));
52	    return success();
53	  }
54	};
55	
56	struct TritonHistogramToHFusionConversion
57	    : OpRewritePattern<triton::HistogramOp> {
58	  using OpRewritePattern<triton::HistogramOp>::OpRewritePattern;
59	
60	  LogicalResult matchAndRewrite(triton::HistogramOp op,
61	                                PatternRewriter &rewriter) const final {
62	    auto loc = op.getLoc();
63	    Value input = op.getSrc();
64	    auto resultType = op.getResult().getType();
65	
66	    int64_t numBins = 256; // 256 is default fallback.
67	    if (auto rankedTy = dyn_cast<RankedTensorType>(resultType))
68	      if (rankedTy.hasStaticShape() && rankedTy.getNumElements() > 0)
69	        numBins = rankedTy.getNumElements();
70	
71	    auto numBinsAttr = rewriter.getI64IntegerAttr(numBins);
72	
73	    auto newOp = rewriter.create<hfusion::HistogramOp>(loc, resultType, input,
74	                                                       numBinsAttr, Value());
75	
76	    rewriter.replaceOp(op, newOp.getResult());
77	    return success();
78	  }
79	};
80	
81	struct TritonFpToFpToHFusionConversion : OpRewritePattern<triton::FpToFpOp> {
82	  using OpRewritePattern<triton::FpToFpOp>::OpRewritePattern;
83	
84	  LogicalResult matchAndRewrite(triton::FpToFpOp op,
85	                                PatternRewriter &rewriter) const final {
86	    auto loc = op.getLoc();
87	    Value input = op.getSrc();
88	    auto resultType = op.getResult().getType();
89	
90	    // Only handle float-to-float conversions with non-RTNE rounding modes
91	    // RTNE (default) rounding is handled by TritonToLinalg pass using
92	    // arith.truncf/extf
93	    auto srcType = cast<TensorType>(input.getType());
94	    auto dstType = cast<TensorType>(resultType);
95	    if (!srcType.getElementType().isIntOrFloat() ||
96	        !dstType.getElementType().isIntOrFloat()) {
97	      return failure();
98	    }
99	
100	    // Check if this has a non-RTNE rounding mode
101	    auto roundingMode = op.getRounding();
102	    if (!roundingMode.has_value() ||
103	        roundingMode.value() == triton::RoundingMode::RTNE) {
104	      // RTNE or no rounding mode specified: let TritonToLinalg handle it
105	      return failure();
106	    }
107	
108	    // Map non-RTNE rounding modes to HFusion rounding mode
109	    hfusion::RoundMode hfusionRoundMode;
110	    switch (roundingMode.value()) {
111	    case triton::RoundingMode::RTZ:
112	      hfusionRoundMode = hfusion::RoundMode::TRUNC;
113	      break;
114	    default:
115	      return op.emitError("Unsupported rounding mode for HFusion conversion");
116	    }
117	    // Note: Only RTZ (and potential future non-RTNE modes) reach here
118	
119	    // Get or create destination tensor (destination-style)
120	    SmallVector<Value> dsts;
121	    if (failed(tensor::getOrCreateDestinations(rewriter, loc, op, dsts)))
122	      return failure();
123	
124	    // Create the HFusion cast operation with round_mode attribute
125	    auto roundModeAttr =
126	        hfusion::RoundModeAttr::get(rewriter.getContext(), hfusionRoundMode);
127	    auto modeAttr = rewriter.getNamedAttr("mode", roundModeAttr);
128	
129	    rewriter.replaceOpWithNewOp<hfusion::CastOp>(
130	        op, ValueRange{input}, ValueRange{dsts}, ArrayRef{modeAttr});
131	
132	    return success();
133	  }
134	};
