136	struct TritonConv1dToHFusionConversion
137	    : OpRewritePattern<triton::ascend::Conv1dOp> {
138	  using OpRewritePattern<triton::ascend::Conv1dOp>::OpRewritePattern;
139	
140	  LogicalResult matchAndRewrite(triton::ascend::Conv1dOp op,
141	                                PatternRewriter &rewriter) const final {
142	    auto loc = op.getLoc();
143	
144	    Value input = op.getInput();
145	    Value weight = op.getWeight();
146	    Value biasValue = op.getBias();
147	    int64_t stride = op.getStride();
148	    int64_t padding_size = op.getPaddingSize();
149	    int64_t dilation = op.getDilation();
150	    int64_t groups = op.getGroups();
151	
152	    auto inputType = mlir::cast<RankedTensorType>(input.getType());
153	    auto weightType = mlir::cast<RankedTensorType>(weight.getType());
154	    if (!inputType.hasStaticShape() || !weightType.hasStaticShape()) {
155	      return failure();
156	    }
157	
158	    ArrayRef<int64_t> inputShape = inputType.getShape();
159	    ArrayRef<int64_t> weightShape = weightType.getShape();
160	
161	    bool isBatched = inputShape.size() == 3;
162	    int64_t N;
163	    if (isBatched)
164	      N = inputShape[0];
165	    int64_t L_in = inputShape[isBatched ? 2 : 1];
166	    int64_t C_out = weightShape[0];
167	    int64_t kernel_size = weightShape[2];
168	
169	    if (stride == 0) {
170	      return failure();
171	    }
172	    int64_t L_out =
173	        (L_in + 2 * padding_size - dilation * (kernel_size - 1) - 1) / stride +
174	        1;
175	
176	    auto resultType = mlir::cast<RankedTensorType>(op.getResult().getType());
177	    Type resultElementType = resultType.getElementType();
178	
179	    constexpr int64_t dim2 = 2;
180	    constexpr int64_t dim3 = 3;
181	    Value initTensor;
182	    if (isBatched) {
183	      SmallVector<int64_t, dim3> outputShape{N, C_out, L_out};
184	      initTensor =
185	          rewriter.create<tensor::EmptyOp>(loc, outputShape, resultElementType);
186	    } else {
187	      SmallVector<int64_t, dim2> outputShape{C_out, L_out};
188	      initTensor =
189	          rewriter.create<tensor::EmptyOp>(loc, outputShape, resultElementType);
190	    }
191	
192	    SmallVector<Value, dim3> ins;
193	    ins.push_back(input);
194	    ins.push_back(weight);
195	    if (biasValue) {
196	      ins.push_back(biasValue);
197	    }
198	
199	    auto newOp = rewriter.create<hfusion::Conv1DOp>(
200	        loc, ins, initTensor, stride, padding_size, dilation, groups);
201	
202	    rewriter.replaceOp(op, newOp.getResult());
203	
204	    return success();
205	  }
