21	using namespace mlir;
22	
23	namespace {
24	struct TritonToLLVMPass
25	    : public mlir::triton::impl::TritonToLLVMBase<TritonToLLVMPass> {
26	  void runOnOperation() override;
27	};
28	} // namespace
29	
30	namespace {
31	
32	static Type getElementType(Value value) {
33	  auto type = value.getType();
34	  if (auto tensorType = dyn_cast<RankedTensorType>(type))
35	    return tensorType.getElementType();
36	  return type;
37	}
38	
39	static int64_t getTensorNumElements(Value tensor) {
40	  auto type = mlir::cast<RankedTensorType>(tensor.getType());
41	  return type.getNumElements();
42	}
43	
44	static Value getInt32Value(RewriterBase &rewriter, Location loc, int val) {
45	  Type ty = rewriter.getI32Type();
46	  return rewriter.create<LLVM::ConstantOp>(loc, ty,
47	                                           rewriter.getIntegerAttr(ty, val));
48	}
49	
50	// If operand size is smaller than 32 bits, pack in groups of 32 bits.
51	SmallVector<Value> packOperands(mlir::triton::ElementwiseInlineAsmOp op,
52	                                const SmallVector<SmallVector<Value>> &operands,
53	                                RewriterBase &rewriter, Location loc) {
54	  SmallVector<Value> packedOperands;
55	  unsigned numPackedElements = op.getPackedElement();
56	  for (int i = 0, e = op.getNumOperands(); i < e; i++) {
57	    Type elemTy = getElementType(op.getOperand(i));
58	    unsigned bitWidth =
59	        elemTy.isIntOrFloat() ? elemTy.getIntOrFloatBitWidth() : 64;
60	    unsigned numElementPerReg = std::max(32 / bitWidth, 1u);
61	    numElementPerReg = std::min(numElementPerReg, numPackedElements);
62	    for (int j = 0; j < numPackedElements; j += numElementPerReg) {
63	      if (numElementPerReg == 1) {
64	        packedOperands.push_back(operands[j][i]);
65	        continue;
66	      }
67	      Type t = VectorType::get(numElementPerReg, elemTy);
68	      Value packed = rewriter.create<LLVM::UndefOp>(loc, t);
69	      for (int k = 0; k < numElementPerReg; k++) {
70	        packed = rewriter.create<LLVM::InsertElementOp>(
71	            loc, packed, operands[j + k][i], getInt32Value(rewriter, loc, k));
72	      }
73	      packedOperands.push_back(packed);
74	    }
75	  }
76	  return packedOperands;
77	}
78	
79	static SmallVector<Value> unpackElements(Location loc, Value packedValues,
80	                                         RewriterBase &rewriter) {
81	  auto type = mlir::cast<RankedTensorType>(packedValues.getType());
82	  auto elementType = type.getElementType();
83	  auto shape = type.getShape();
84	
85	  int64_t numElements = type.getNumElements();
86	
87	  SmallVector<Value> result;
88	  for (int64_t linearIdx = 0; linearIdx < numElements; linearIdx++) {
89	    SmallVector<Value> indexes(shape.size());
90	    int64_t remaining = linearIdx;
91	    for (int64_t dim = shape.size() - 1; dim >= 0; dim--) {
92	      indexes[dim] =
93	          rewriter.create<arith::ConstantIndexOp>(loc, remaining % shape[dim]);
94	      remaining /= shape[dim];
95	    }
96	    Value extracted = rewriter.create<tensor::ExtractOp>(loc, elementType,
97	                                                         packedValues, indexes);
98	    result.push_back(extracted);
99	  }
100	
101	  return result;
102	}
103	
104	static SmallVector<SmallVector<Value>>
105	createDestOps(triton::ElementwiseInlineAsmOp op, RewriterBase &rewriter,
106	              const SmallVector<SmallVector<Value>> operands, Location loc) {
107	  auto ctx = op->getContext();
108	  if (operands.size() % op.getPackedElement() != 0)
109	    llvm::report_fatal_error("Inline asm op has more packed elements than "
110	                             "number of elements per thread.");
111	
112	  // Pack elems smaller than 32 bits into 32-bit registers.
113	  SmallVector<Value> packedOperands = packOperands(op, operands, rewriter, loc);
114	
115	  // Types returned by the LLVM asm op.  If there's more than one, they'll be
116	  // wrapped in a type tuple.
117	  SmallVector<Type> asmRetTypes;
118	  for (auto result : op.getResult()) {
119	    auto ty = getElementType(result);
120	
121	    // Pack return elements into 32-bits.
122	    unsigned bitWidth = ty.isIntOrFloat() ? ty.getIntOrFloatBitWidth() : 64;
123	    unsigned numElemsPerReg =
124	        std::min(std::max(32 / bitWidth, 1u), op.getPackedElement());
125	    assert(op.getPackedElement() % numElemsPerReg == 0);
126	    if (numElemsPerReg > 1) {
127	      ty = VectorType::get(numElemsPerReg, ty);
128	    }
129	    for (unsigned i = 0; i < op.getPackedElement() / numElemsPerReg; i++) {
130	      asmRetTypes.push_back(ty);
131	    }
132	  }
133	  Type asmRetType = asmRetTypes.size() > 1
134	                        ? LLVM::LLVMStructType::getLiteral(ctx, asmRetTypes)
135	                        : asmRetTypes[0];
136	
137	  Value asmResults =
138	      rewriter
139	          .create<LLVM::InlineAsmOp>(
140	              loc, asmRetType,
141	              /*operands=*/packedOperands,
142	              /*asm_string=*/op.getAsmString(),
143	              /*constraints=*/op.getConstraints(),
144	              /*has_side_effects=*/!op.getPure(),
145	              /*is_align_stack=*/false,
146	              /*tail_call_kind=*/LLVM::tailcallkind::TailCallKind::None,
147	              /*asm_dialect=*/
148	              LLVM::AsmDialectAttr::get(rewriter.getContext(),
149	                                        LLVM::AsmDialect::AD_ATT),
150	              /*operand_attrs=*/ArrayAttr())
151	          ->getResult(0);
152	
153	  // asmResults is a flat struct; pack its values into
154	  // [return_value][op.getPackedElement()].
155	  SmallVector<SmallVector<Value>> ret(op->getNumResults());
156	  int structIdx = 0;
157	  for (int i = 0; i < op->getNumResults(); i++) {
158	    for (int j = 0; j < op.getPackedElement(); j++) {
159	      Value val;
160	      if (asmRetTypes.size() > 1) {
161	        val =
162	            rewriter.create<LLVM::ExtractValueOp>(loc, asmResults, structIdx++);
163	      } else {
164	        val = asmResults;
165	      }
166	      if (auto vectorTy = dyn_cast<VectorType>(val.getType())) {
167	        for (int k = 0; k < vectorTy.getNumElements(); k++) {
168	          ret[i].push_back(rewriter.create<LLVM::ExtractElementOp>(
169	              loc, val, getInt32Value(rewriter, loc, k)));
170	        }
171	        j += vectorTy.getNumElements() - 1;
172	      } else {
173	        ret[i].push_back(val);
174	      }
175	    }
176	  }
177	  return ret;
178	}
179	
180	static LogicalResult processScalarInlineAsm(triton::ElementwiseInlineAsmOp op,
181	                                            PatternRewriter &rewriter) {
182	  Location loc = op.getLoc();
183	
184	  auto outsWrapped = createDestOps(op, rewriter, {}, loc);
185	
186	  SmallVector<Value> outs;
187	  for (const auto &resWrapped : outsWrapped) {
188	    outs.push_back(resWrapped[0]);
189	  }
190	  rewriter.replaceOp(op, outs);
191	
192	  return success();
193	}
194	
195	static LogicalResult processVectorInlineAsm(triton::ElementwiseInlineAsmOp op,
196	                                            PatternRewriter &rewriter) {
197	  Location loc = op.getLoc();
198	
199	  SmallVector<SmallVector<Value>> unpackedOperands;
200	  for (auto operand : op.getOperands()) {
201	    auto unpackedOperand = unpackElements(loc, operand, rewriter);
202	    unpackedOperands.push_back(unpackedOperand);
203	  }
204	
205	  int64_t resultLength = getTensorNumElements(op->getResult(0));
206	  if (resultLength % op.getPackedElement()) {
207	    op.emitError("Result tensor should be diveded to pack");
208	    return failure();
209	  }
210	
211	  SmallVector<SmallVector<Value>> unpackedResults(op->getNumResults());
212	  for (int64_t i = 0; i < resultLength; i += op.getPackedElement()) {
213	    // Block of elements to process with one call to the inline asm.  This is
214	    // ordered opposite `unpackedResults`: The outer dim is
215	    // op.getPackedElement(), and the inner dim is the operand.
216	    SmallVector<SmallVector<Value>> block(op.getPackedElement());
217	    for (auto &os : unpackedOperands) {
218	      for (int j = 0; j < op.getPackedElement(); j++) {
219	        block[j].push_back(os[i + j]);
220	      }
221	    }
222	    auto cur = createDestOps(op, rewriter, block, loc);
223	    assert(cur.size() == unpackedResults.size());
224	    for (unsigned j = 0; j < cur.size(); j++) {
225	      unpackedResults[j].insert(unpackedResults[j].end(), cur[j].begin(),
226	                                cur[j].end());
227	    }
228	  }
229	  // Reorder and pack the results.
230	  SmallVector<Value> outs;
231	  for (int i = 0; i < unpackedResults.size(); i++) {
232	    outs.push_back(rewriter.create<tensor::FromElementsOp>(
233	        loc, op->getResult(i).getType(), unpackedResults[i]));
234	  }
235	  rewriter.replaceOp(op, outs);
236	
237	  return success();
238	}
239	
240	} // namespace
241	
